UPDATE product_images SET is_primary=0 WHERE r2_key IN ('catalogue/dualsense-midnight-black.png','catalogue/dualsense-cosmic-red.png') AND product_id IN ('catalog-dualsense-midnight-black','catalog-dualsense-cosmic-red');
UPDATE product_images SET is_primary=1 WHERE r2_key IN ('catalogue/inventory-dualsense-midnight-black.webp','catalogue/inventory-dualsense-cosmic-red.webp') AND NOT EXISTS(SELECT 1 FROM product_images current_image WHERE current_image.product_id=product_images.product_id AND current_image.is_primary=1);
